trait UserProfilePreferredUsernameAttributeHolder
{
    protected UserProfilePreferredUsernameVO|string|null $preferredUsername = null;
    protected bool $preferredUsernameAssigned = false;

    public function getPreferredUsernameOrCurrent(?UserProfilePreferredUsernameVO $preferredUsername): ?UserProfilePreferredUsernameVO
    {
        return $this->preferredUsernameAssigned ? ($this->preferredUsername === null ? null : UserProfilePreferredUsernameVO::from($this->preferredUsername)) : $preferredUsername;
    }
    public function preferredUsernameTryBuildInitial(ConstraintFailList $error): ?UserProfilePreferredUsernameVO
    {
        return  UserProfilePreferredUsernameVO::tryFrom($this->preferredUsernameAssigned ? $this->preferredUsername : null, $error);
    }
    public function preferredUsername(UserProfilePreferredUsernameVO|string|null $preferredUsername): static
    {
        $this->preferredUsername = $preferredUsername;
        $this->preferredUsernameAssigned = true;
        return $this;
    }
    public function getPreferredUsername(): ?string
    {
        return $this->preferredUsername instanceof UserProfilePreferredUsernameVO ? $this->preferredUsername->value() : $this->preferredUsername;
    }
    public function isPreferredUsernameAssigned(): bool
    {
        return $this->preferredUsernameAssigned;
    }
    public function writePreferredUsernameTo(mixed $att): void
    {
        if ($this->preferredUsernameAssigned) {
            $att->preferredUsername($this->preferredUsername);
        }
    }
    public function readPreferredUsernameFrom(mixed $att): void
    {
        if ($att->isPreferredUsernameAssigned()) {
            $preferredUsername = $att->getPreferredUsername();
            $this->preferredUsername($preferredUsername);
        }
    }
    public function unsetPreferredUsername(): static
    {
        $this->preferredUsernameAssigned = false;
        return $this;
    }
    protected function withDefaultPreferredUsername(): void
