    }
    protected function withAssertedPreferredUsernameRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->preferredUsernameAssigned = $this->preferredUsernameAssigned) {
            $value->preferredUsername = UserProfilePreferredUsernameVO::tryFrom($this->preferredUsername, $errorsList);
        }
    }
}
